"""V-123: geometry / pixel-density / blur / storage / budget arithmetic for PROCUREMENT.md.

Inputs are datasheet numbers (sources in sources.md) and explicit assumptions marked ASSUMPTION.
Stdlib only, deterministic. Usage: python3 -I geometry_calc.py > raw/geometry_calc_output.txt
"""
import math

CAMS = {
    # name: (h_pixels, fps_at_max_res, [(lens, hfov_deg, dori_detect_m)], source)
    "Uniview IPC2324LB-ADZK-H": (2688, 25, [("2.8 mm", 91.5, 63.0), ("12 mm", 34.0, 270.0)], "global.uniview.com page (datasheet 2026-06-02)"),
    "Hikvision DS-2CD2643G2-IZS": (2688, 25, [("2.8 mm", 95.8, 64.0), ("12 mm", 29.2, 200.0)], "DSSL card table / datasheet v5.5.113 summary"),
    "Hikvision DS-2CD2647G2HT-LIZS": (2688, 25, [("2.8 mm", 114.6, 60.0), ("12 mm", 41.8, 149.0)], "DSSL card"),
    "Uniview IPC328LE-ADF28K-G": (3840, 20, [("2.8 mm", 112.9, 84.0)], "DSSL card + Uniview IT datasheet summary (20 fps @8MP)"),
    "Hikvision DS-2CD2387G2H-LIU 4mm": (3840, 25, [("4 mm", 93.3, 109.0)], "DSSL card (DoF 3.3 m..inf)"),
}

# IEC 62676-4:2025 functional levels (pixels per metre at the target)
LEVELS = {"discern (objects+movements)": 80, "characterise (action of a person)": 250, "validate": 500}


def k_dori(detect_m):
    """DORI 'Detect' = 25 px/m, so centre density at distance d is 25*D/d."""
    return 25.0 * detect_m


def k_hfov(hpx, hfov):
    """Average density across the frame width: hpx / (2 d tan(hfov/2))."""
    return hpx / (2.0 * math.tan(math.radians(hfov / 2.0)))


print("== 1. Pixel density K/d (px/m at distance d metres) and max distance for each IEC level")
print("   K_dori = centre-of-frame (vendor DORI), K_hfov = frame-average (datasheet HFOV); design with the lower one")
for name, (hpx, fps, lenses, src) in CAMS.items():
    for lens, hfov, det in lenses:
        kd, kh = k_dori(det), k_hfov(hpx, hfov)
        k = min(kd, kh)
        row = ", ".join(f"{lvl.split()[0]} {p}px/m <= {k / p:.1f} m" for lvl, p in LEVELS.items())
        print(f"{name} @{lens}: K_dori={kd:.0f} K_hfov={kh:.0f} -> {row}  [{src}]")

print("\n== 2. Lens-independent: max covered width at a target density = horizontal pixels / P")
for hpx in (2688, 3840):
    print(f"  {hpx} px: " + ", ".join(f"{p} px/m -> {hpx / p:.2f} m" for p in LEVELS.values()))

print("\n== 3. Detector-input check: object height at model input = h_obj * P * (input_w / sensor_w); COCO 'small' < 32 px")
for input_w in (640, 1280):
    for hpx in (2688, 3840):
        s = input_w / hpx
        for h_obj, what in ((1.7, "standing person 1.7 m (ASSUMPTION)"), (1.0, "bent/seated person 1.0 m (ASSUMPTION)")):
            pmin = 32.0 / (h_obj * s)
            print(f"  input {input_w}px from {hpx}px, {what}: P_min = {pmin:.0f} px/m")

print("\n== 4. Overhead hands/material camera: min height above table to fit table length L across the frame width")
for name, hfov in (("Uniview IPC2324LB-ADZK-H wide 91.5deg", 91.5), ("Hikvision DS-2CD2647G2HT-LIZS wide 114.6deg", 114.6),
                   ("Hikvision DS-2CD2643G2-IZS wide 95.8deg", 95.8)):
    for L in (1.6, 2.0, 3.2, 5.0):
        h = L / (2 * math.tan(math.radians(hfov / 2)))
        print(f"  {name}: L={L} m (ASSUMPTION, measure) -> h_min={h:.2f} m above table; avg density if zoomed to fit L exactly = {2688 / L:.0f} px/m")

print("\n== 5. Required HFOV when the mount height h above the table is fixed (zoom setting check)")
for h in (1.5, 2.0, 2.5, 3.0):
    for L in (2.0, 3.2):
        need = 2 * math.degrees(math.atan(L / (2 * h)))
        print(f"  h={h} m, L={L} m -> HFOV needed {need:.1f} deg (Uniview range 34..91.5, Hikvision 2647 41.8..114.6)")

print("\n== 6. Motion blur in pixels = v * t_exp * P (v ASSUMPTION, to be measured on a test clip)")
for v, what in ((1.4, "walking 1.4 m/s"), (0.5, "hand 0.5 m/s"), (2.0, "fast hand 2 m/s")):
    for t in (1 / 100, 1 / 200, 1 / 500):
        for p in (80, 250, 500, 840):
            print(f"  {what}, t=1/{round(1 / t)} s, P={p}: blur {v * t * p:.1f} px")

print("\n== 7. Storage = bitrate * time (decimal GB/TB)")
for mbps in (2, 4, 6):
    gb_day = mbps * 1e6 / 8 * 86400 / 1e9
    print(f"  {mbps} Mbit/s 24h: {gb_day:.1f} GB/day/camera; 12h shift: {gb_day / 2:.1f} GB")
for cams, mbps, hours, days in ((5, 4, 24, 14), (5, 4, 24, 30), (5, 4, 12, 30), (12, 4, 24, 30), (24, 4, 24, 30)):
    tb = cams * mbps * 1e6 / 8 * 3600 * hours * days / 1e12
    print(f"  {cams} cams x {mbps} Mbit/s x {hours} h/day x {days} days = {tb:.2f} TB")

print("\n== 8. Network/PoE budget")
for cams, w, sw in ((5, 9.6, 120), (5, 15.0, 120), (8, 9.6, 120), (8, 15.0, 120)):
    print(f"  {cams} cams x {w} W = {cams * w:.1f} W vs switch PoE budget {sw} W -> headroom {sw - cams * w:.1f} W")
for cams, mbps in ((5, 6 + 1), (24, 6 + 1)):
    print(f"  {cams} cams x {mbps} Mbit/s (main max + sub) = {cams * mbps} Mbit/s vs 1000 Mbit/s uplink")…

